import React from "react";

function Home() {
  return (
    <div style={{
      padding: "40px",
      textAlign: "center"
    }}>
      
      <h1 style={{
        fontSize: "40px",
        color: "#0B5ED7"
      }}>
        Welcome to LawBridge
      </h1>

      <p style={{
        fontSize: "18px",
        marginTop: "15px"
      }}>
        Find trusted lawyers and book appointments easily.
      </p>

      <button style={{
        marginTop: "20px",
        padding: "12px 25px",
        backgroundColor: "#0B5ED7",
        color: "white",
        border: "none",
        borderRadius: "6px",
        fontSize: "16px",
        cursor: "pointer"
      }}>
        Find Lawyer
      </button>

    </div>
  );
}

export default Home;
